import stat
for mode in (0o644, 0o755, 0o600, 0o777):
    print(f"{mode:o}", stat.filemode(stat.S_IFREG | mode))

def explain(mode):
    for i, who in enumerate(("owner", "group", "others")):
        bits = (mode >> (6 - 3 * i)) & 7
        allowed = [name for name, bit in (("read", 4), ("write", 2), ("execute", 1)) if bits & bit]
        print(f"{who}: {', '.join(allowed) or 'nothing'}")

explain(0o640)

def classify(port):
    """Return the IANA range of a TCP or UDP port number."""
    if port < 0 or port > 65535:
        raise ValueError("not a valid port number")
    if port < 1024:
        return "well-known"
    elif port < 49152:
        return "registered"
    return "dynamic"

for p in (22, 443, 8080, 50000):
    print(p, classify(p))

def parse_port(text):
    try:
        port = int(text)
    except ValueError:
        return None, f"not a number: {text!r}"
    if not 0 <= port <= 65535:
        return None, f"out of range: {port}"
    return port, None

for entry in ("443", "12a", "70000"):
    print(parse_port(entry))

def linear_steps(items, target):
    steps = 0
    for x in items:
        steps += 1
        if x == target:
            break
    return steps

def binary_steps(items, target):
    lo, hi, steps = 0, len(items) - 1, 0
    while lo <= hi:
        steps += 1
        mid = (lo + hi) // 2
        if items[mid] == target:
            return steps
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps

for n in (10, 1_000, 1_000_000):
    items = list(range(n))
    print(f"n={n:>9,}  linear={linear_steps(items, n - 1):>9,}  binary={binary_steps(items, n - 1):>3}")

def top_words(text, n):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    ranked = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ranked[:n]

sample = "alpha beta alpha gamma beta alpha gamma gamma gamma"
for word, count in top_words(sample, 3):
    print(word, count)

assert top_words("b a b", 1) == [("b", 2)]
assert top_words("A a", 1) == [("a", 2)]
